from smolagents import Tool


class SpraayBatchSendEthTool(Tool):
    name = "spraay_batch_send_eth"
    description = (
        "Send the same amount of ETH to many recipients (max 200) in one transaction on Base "
        "using the Spraay batch contract. This moves real funds from the wallet in SPRAAY_PRIVATE_KEY. "
        "A 0.3% protocol fee is added on top of the total. Returns a status line with the Basescan link."
    )
    inputs = {
        "recipients": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Recipient wallet addresses (0x...), at most 200.",
        },
        "amount_each_ether": {
            "type": "string",
            "description": "ETH each recipient receives, as a decimal string, e.g. '0.001'.",
        },
    }
    output_type = "string"
    SPRAAY_CONTRACT = "0x1646452F98E36A3c9Cfc3eDD8868221E207B5eEC"
    BASE_CHAIN_ID = 8453
    DEFAULT_RPC = "https://mainnet.base.org"
    FALLBACK_FEE_BPS = 30
    MAX_FEE_BPS = 500
    MAX_RECIPIENTS = 200
    RECEIPT_TIMEOUT = 180
    ZERO_ADDRESS = "0x0000000000000000000000000000000000000000"
    SPRAAY_ABI_JSON = "[{\"name\":\"sprayETH\",\"type\":\"function\",\"inputs\":[{\"name\":\"recipients\",\"type\":\"tuple[]\",\"components\":[{\"name\":\"recipient\",\"type\":\"address\"},{\"name\":\"amount\",\"type\":\"uint256\"}]}],\"outputs\":[],\"stateMutability\":\"payable\"},{\"name\":\"sprayToken\",\"type\":\"function\",\"inputs\":[{\"name\":\"token\",\"type\":\"address\"},{\"name\":\"recipients\",\"type\":\"tuple[]\",\"components\":[{\"name\":\"recipient\",\"type\":\"address\"},{\"name\":\"amount\",\"type\":\"uint256\"}]}],\"outputs\":[],\"stateMutability\":\"nonpayable\"},{\"name\":\"sprayEqual\",\"type\":\"function\",\"inputs\":[{\"name\":\"token\",\"type\":\"address\"},{\"name\":\"recipients\",\"type\":\"address[]\"},{\"name\":\"amountPerRecipient\",\"type\":\"uint256\"}],\"outputs\":[],\"stateMutability\":\"payable\"},{\"name\":\"feeBps\",\"type\":\"function\",\"inputs\":[],\"outputs\":[{\"name\":\"\",\"type\":\"uint256\"}],\"stateMutability\":\"view\"}]"
    ERC20_ABI_JSON = "[{\"name\":\"approve\",\"type\":\"function\",\"inputs\":[{\"name\":\"spender\",\"type\":\"address\"},{\"name\":\"amount\",\"type\":\"uint256\"}],\"outputs\":[{\"name\":\"\",\"type\":\"bool\"}],\"stateMutability\":\"nonpayable\"},{\"name\":\"allowance\",\"type\":\"function\",\"inputs\":[{\"name\":\"owner\",\"type\":\"address\"},{\"name\":\"spender\",\"type\":\"address\"}],\"outputs\":[{\"name\":\"\",\"type\":\"uint256\"}],\"stateMutability\":\"view\"},{\"name\":\"decimals\",\"type\":\"function\",\"inputs\":[],\"outputs\":[{\"name\":\"\",\"type\":\"uint8\"}],\"stateMutability\":\"view\"}]"

    def _check_recipients(self, recipients):
        """Validate the recipient list and return checksummed addresses."""
        from web3 import Web3

        if not isinstance(recipients, (list, tuple)) or len(recipients) == 0:
            raise ValueError("Recipients must be a non-empty list of addresses.")
        if len(recipients) > self.MAX_RECIPIENTS:
            raise ValueError("Maximum 200 recipients per transaction.")
        checksummed = []
        for address in recipients:
            if not isinstance(address, str) or not Web3.is_address(address):
                raise ValueError(f"Invalid address: {address}")
            body = address[2:]
            if body != body.lower() and body != body.upper() and not Web3.is_checksum_address(address):
                raise ValueError(f"Address has a bad checksum (possible typo): {address}")
            checksummed.append(Web3.to_checksum_address(address))
        return checksummed

    def _to_units(self, amount, decimals):
        """Convert a human amount (string) to integer base units, exactly."""
        from decimal import Decimal, InvalidOperation

        try:
            value = Decimal(str(amount).strip())
        except InvalidOperation:
            raise ValueError(f"Invalid amount: {amount}") from None
        if not value.is_finite() or value <= 0:
            raise ValueError(f"Amount must be greater than 0, got: {amount}")
        scaled = value * (Decimal(10) ** decimals)
        if scaled != scaled.to_integral_value():
            raise ValueError(f"Amount {amount} has more than {decimals} decimal places.")
        return int(scaled)

    def _connect(self):
        """Return (w3, account, spraay_contract) for Base mainnet."""
        import json
        import os

        from web3 import Web3

        private_key = os.environ.get("SPRAAY_PRIVATE_KEY")
        if not private_key:
            raise ValueError("Set the SPRAAY_PRIVATE_KEY environment variable.")
        rpc_url = os.environ.get("SPRAAY_RPC_URL") or self.DEFAULT_RPC
        w3 = Web3(Web3.HTTPProvider(rpc_url))
        chain_id = w3.eth.chain_id
        if chain_id != self.BASE_CHAIN_ID:
            raise ValueError(f"RPC chain ID {chain_id} is not Base mainnet ({self.BASE_CHAIN_ID}).")
        account = w3.eth.account.from_key(private_key)
        contract = w3.eth.contract(address=Web3.to_checksum_address(self.SPRAAY_CONTRACT), abi=json.loads(self.SPRAAY_ABI_JSON))
        return w3, account, contract

    def _fee(self, contract, total):
        """Protocol fee on `total`, using the contract's live feeBps()."""
        fee_bps = self.FALLBACK_FEE_BPS
        try:
            live = contract.functions.feeBps().call()
            if isinstance(live, int) and 0 <= live <= self.MAX_FEE_BPS:
                fee_bps = live
        except Exception:
            fee_bps = self.FALLBACK_FEE_BPS
        return (total * fee_bps) // 10000

    def _send(self, w3, account, call, value=0):
        """Estimate, sign, send and wait. Returns (tx_hash_hex, succeeded)."""
        tx = call.build_transaction(
            {
                "from": account.address,
                "value": value,
                "chainId": self.BASE_CHAIN_ID,
                "nonce": w3.eth.get_transaction_count(account.address, "pending"),
            }
        )
        tx["gas"] = int(tx["gas"] * 1.2)
        signed = account.sign_transaction(tx)
        tx_hash = w3.eth.send_raw_transaction(signed.raw_transaction)
        receipt = w3.eth.wait_for_transaction_receipt(tx_hash, timeout=self.RECEIPT_TIMEOUT)
        return w3.to_hex(tx_hash), receipt["status"] == 1

    def forward(self, recipients, amount_each_ether):
        try:
            addresses = self._check_recipients(recipients)
            amount_wei = self._to_units(amount_each_ether, 18)
            total_wei = amount_wei * len(addresses)
            w3, account, contract = self._connect()
            fee_wei = self._fee(contract, total_wei)
            # sprayEqual with token = address(0) is the contract's native-ETH path.
            call = contract.functions.sprayEqual(self.ZERO_ADDRESS, addresses, amount_wei)
            tx_hash, ok = self._send(w3, account, call, total_wei + fee_wei)
            return (
                f"Batch ETH sent! Recipients: {len(addresses)}, Amount each: {amount_each_ether} ETH, "
                f"Total incl. fee: {w3.from_wei(total_wei + fee_wei, 'ether')} ETH, "
                f"Status: {'Success' if ok else 'Failed'}, Tx: https://basescan.org/tx/{tx_hash}"
            )
        except Exception as e:
            return f"Error: {e}"


